INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m1-016', 'c1-m1-i11', 'calculus-1', 'c1-m1', 0, '小测：极限存在', '下列极限存在的是（ ）', '["\\\\( \\\\displaystyle\\\\lim_{x\\\\to0}\\\\frac{1}{x} \\\\)","\\\\( \\\\displaystyle\\\\lim_{x\\\\to0}\\\\frac{x}{x} \\\\)","\\\\( \\\\displaystyle\\\\lim_{x\\\\to0}\\\\sin\\\\frac{1}{x} \\\\)","\\\\( \\\\displaystyle\\\\lim_{x\\\\to\\\\infty}\\\\sin x \\\\)"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '\\( \\lim_{x\\to0}\\frac{x}{x}=1 \\) 存在；其余分别为 \\( \\infty \\) 或不存在。', NULL, NULL, NULL, 2, '["极限"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m1-017', 'c1-m1-i11', 'calculus-1', 'c1-m1', 0, '小测：数列极限', '求 \\( \\displaystyle \\lim_{n\\to\\infty}\\left(\\frac{1}{2}\\right)^n \\)。', '["0","-1","2","1"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '公比绝对值小于 1 的几何数列极限为 0。', NULL, NULL, NULL, 2, '["数列极限"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m2-001', 'c1-m2-i1', 'calculus-1', 'c1-m2', 0, '用定义求导数', '设 \\( f(x)=x^2 \\)，用导数定义求 \\( f^{\\prime}(1) \\)。', '["3","2","1","4"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '\\( \\lim_{h\\to0}\\frac{(1+h)^2-1}{h}=\\lim_{h\\to0}(2+h)=2 \\)。', NULL, NULL, NULL, 2, '["导数"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m2-002', 'c1-m2-i1', 'calculus-1', 'c1-m2', 0, '导数的几何意义', '函数 \\( y=f(x) \\) 在 \\( x_0 \\) 处的导数 \\( f^{\\prime}(x_0) \\) 表示曲线在该点处（ ）', '["切线的斜率","法线的斜率","割线的斜率","曲率"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '导数为切线斜率。', NULL, NULL, NULL, 2, '["导数"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m2-003', 'c1-m2-i2', 'calculus-1', 'c1-m2', 0, '基本求导', '求 \\( y=x^3-2x^2+5x-1 \\) 的导数 \\( y^{\\prime} \\)。', '["3x^2-4x+5+1","3x^2-4x","3x^2-4x-5","3x^2-4x+5"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '逐项求导。', NULL, NULL, NULL, 2, '["求导法则"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m2-004', 'c1-m2-i2', 'calculus-1', 'c1-m2', 0, '乘积法则', '求 \\( y=x^2\\sin x \\) 的导数 \\( y^{\\prime} \\)。', '["2xsinx+x^2cosx-1","2xsinx+x^2cosx","2xsinx-x^2cosx","2xsinx+x^2cosx+1"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '乘积法则：\\( (x^2)^{\\prime}\\sin x+x^2(\\sin x)^{\\prime} \\)。', NULL, NULL, NULL, 2, '["求导法则"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m2-005', 'c1-m2-i2', 'calculus-1', 'c1-m2', 0, '商的求导', '求 \\( y=\\frac{e^x}{x} \\) 的导数 \\( y^{\\prime} \\)。', '["(e^x*x-e^x)/x^2+1","(e^x*x-e^x)/x^2","(e^x*x-e^x)/x^2-1","(e^x*x+e^x)/x^2"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '商的法则：\\( \\frac{e^x\\cdot x-e^x\\cdot1}{x^2} \\)。', NULL, NULL, NULL, 2, '["求导法则"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m2-006', 'c1-m2-i3', 'calculus-1', 'c1-m2', 0, '二阶导数', '设 \\( y=\\sin x \\)，求 \\( y^{\\prime\\prime} \\)。', '["-cosx","-sinx-1","-sinx","-sinx+1"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '\\( y^{\\prime}=\\cos x \\)，\\( y^{\\prime\\prime}=-\\sin x \\)。', NULL, NULL, NULL, 2, '["高阶导数"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m2-007', 'c1-m2-i4', 'calculus-1', 'c1-m2', 0, '隐函数求导', '由方程 \\( x^2+y^2=1 \\) 确定的隐函数，求 \\( \\frac{dy}{dx} \\) 在点 \\( (0,1) \\) 处的值。', '["0","2","1","-1"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '两边求导：\\( 2x+2yy^{\\prime}=0 \\)，代入 \\( (0,1) \\) 得 \\( y^{\\prime}=0 \\)。', NULL, NULL, NULL, 2, '["隐函数"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m2-008', 'c1-m2-i5', 'calculus-1', 'c1-m2', 0, '微分的定义', '若 \\( y=f(x) \\) 可微，则 \\( dy=\\) __________。', '["f(x)dx-1","f(x)dx+1","选项1","f(x)dx"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '微分 \\( dy=f^{\\prime}(x)\\,dx \\)。', NULL, NULL, NULL, 2, '["微分"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m2-009', 'c1-m2-i6', 'calculus-1', 'c1-m2', 0, '参数方程求导', '设 \\( \\begin{cases}x=t^2,\\\\ y=t^3,\\end{cases} \\) 求 \\( \\frac{dy}{dx} \\)。', '["3t/2+1","选项1","3t/2-1","3t/2"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '\\( \\frac{dy}{dx}=\\frac{dy/dt}{dx/dt}=\\frac{3t^2}{2t}=\\frac{3t}{2} \\)。', NULL, NULL, NULL, 2, '["参数方程"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m2-010', 'c1-m2-i6', 'calculus-1', 'c1-m2', 0, '复合函数求导', '求 \\( y=\\ln(\\cos x) \\) 的导数。', '["-tanx","选项1","-tanx-1","-tanx+1"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '链式法则：\\( y^{\\prime}=\\frac{1}{\\cos x}\\cdot(-\\sin x)=-\\tan x \\)。', NULL, NULL, NULL, 2, '["求导法则"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m2-011', 'c1-m2-i7', 'calculus-1', 'c1-m2', 1, '小测：求导法则', '下列求导正确的是（ ）', '["A. \\\\( (\\\\sin x)^{\\\\prime}=\\\\cos x \\\\)","B. \\\\( (\\\\cos x)^{\\\\prime}=\\\\sin x \\\\)","C. \\\\( (e^x)^{\\\\prime}=e^x \\\\)","D. \\\\( (x^3)^{\\\\prime}=2x^2 \\\\)"]'::jsonb, '[''0'', ''2'']', '[]'::jsonb, NULL, NULL, NULL, 'A: \\( (\\sin x)^{\\prime}=\\cos x \\) 对；C: \\( (e^x)^{\\prime}=e^x \\) 对。', NULL, NULL, NULL, 2, '["求导法则"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m3-001', 'c1-m3-i1', 'calculus-1', 'c1-m3', 0, '罗尔定理条件', '罗尔定理要求函数在闭区间 [a,b] 上连续，在开区间 (a,b) 内可导，且端点函数值 __________。', '["小于","大于","不相等","相等"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '罗尔定理要求函数在端点处函数值相等。', NULL, NULL, NULL, 2, '["中值定理"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m3-002', 'c1-m3-i1', 'calculus-1', 'c1-m3', 0, '拉格朗日中值定理应用', '证明：当 \\( x>0 \\) 时，\\( \\ln(1+x)<x \\)。', '["以上都不是","见解析","略","证明见解析"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '设 \\( f(t)=\\ln(1+t) \\)，在 \\( [0,x] \\) 上用拉格朗日中值定理：\\( \\frac{\\ln(1+x)-\\ln1}{x}=\\frac{1}{1+\\xi}<1 \\)，其中 \\( 0<\\xi<x \\)，故 \\( \\ln(1+x)<x \\)。', NULL, NULL, NULL, 2, '["中值定理"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m3-003', 'c1-m3-i2', 'calculus-1', 'c1-m3', 0, '洛必达法则 0/0', '求 \\( \\displaystyle \\lim_{x\\to0}\\frac{e^x-1}{x} \\)。', '["0","1","2","-1"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '分子分母均趋于 0，用洛必达法则：\\( \\lim_{x\\to0}\\frac{e^x}{1}=1 \\)。', NULL, NULL, NULL, 2, '["洛必达法则"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m3-004', 'c1-m3-i2', 'calculus-1', 'c1-m3', 0, '洛必达法则 \\(\\infty/\\infty\\)', '求 \\( \\displaystyle \\lim_{x\\to+\\infty}\\frac{\\ln x}{x} \\)。', '["0","2","-1","1"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '\\(\\infty/\\infty\\) 型，洛必达得 \\( \\lim_{x\\to+\\infty}\\frac{1/x}{1}=0 \\)。', NULL, NULL, NULL, 2, '["洛必达法则"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m3-005', 'c1-m3-i3', 'calculus-1', 'c1-m3', 0, '泰勒公式', '\\( e^x \\) 在 \\( x=0 \\) 处的二阶泰勒多项式为 __________。', '["1+x+x^2/2-1","1+x+x^2/2","1+x+x^2/2+1","1+x-x^2/2"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '\\( e^x=1+x+\\frac{x^2}{2!}+o(x^2) \\)。', NULL, NULL, NULL, 2, '["泰勒公式"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m3-006', 'c1-m3-i4', 'calculus-1', 'c1-m3', 0, '求极值', '求 \\( f(x)=x^3-3x \\) 的极大值点与极小值点（用英文分号分隔，如“-1;1”）。', '["1,1","0,0","-1,1","-1;1"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '\\( f^{\\prime}(x)=3x^2-3=0 \\)，得 \\( x=\\pm1 \\)；\\( f^{\\prime\\prime}(-1)=-6<0 \\) 为极大值点，\\( f^{\\prime\\prime}(1)=6>0 \\) 为极小值点。', NULL, NULL, NULL, 2, '["极值"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m3-007', 'c1-m3-i4', 'calculus-1', 'c1-m3', 5, '单调性判定', '若 \\( f^{\\prime}(x)>0 \\) 在区间 \\( I \\) 内恒成立，则 \\( f(x) \\) 在 \\( I \\) 上单调递增。', '["正确","错误"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '导数正则函数递增。', NULL, NULL, NULL, 2, '["单调性"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m3-008', 'c1-m3-i5', 'calculus-1', 'c1-m3', 0, '曲线的渐近线', '曲线 \\( y=\\frac{1}{x} \\) 的水平渐近线为 __________。', '["y=0","y=1","y=-1","选项1"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '\\( x\\to\\infty \\) 时 \\( y\\to0 \\)。', NULL, NULL, NULL, 2, '["渐近线"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m3-009', 'c1-m3-i5', 'calculus-1', 'c1-m3', 0, '曲率', '求抛物线 \\( y=x^2 \\) 在 \\( (0,0) \\) 处的曲率 \\( K \\)。', '["2","4","3","1"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '\\( K=\\frac{|y^{\\prime\\prime}|}{(1+(y^{\\prime})^2)^{3/2}}=\\frac{2}{(1+0)^{3/2}}=2 \\)。', NULL, NULL, NULL, 2, '["曲率"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m3-010', 'c1-m3-i6', 'calculus-1', 'c1-m3', 0, '证明不等式', '证明：当 \\( x>0 \\) 时，\\( \\ln(1+x)>\\frac{x}{1+x} \\)。', '["见解析","以上都不是","证明见解析","略"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '设 \\( f(x)=\\ln(1+x)-\\frac{x}{1+x} \\)，则 \\( f(0)=0 \\)，\\( f^{\\prime}(x)=\\frac{1}{1+x}-\\frac{1}{(1+x)^2}=\\frac{x}{(1+x)^2}>0 \\)，故 \\( f(x)>0 \\)。', NULL, NULL, NULL, 2, '["不等式"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m3-011', 'c1-m3-i7', 'calculus-1', 'c1-m3', 0, '小测：中值定理', '下列函数在 \\( [-1,1] \\) 上满足罗尔定理条件的是（ ）', '["\\\\( x \\\\)","\\\\( |x| \\\\)","\\\\( 1-x^2 \\\\)","\\\\( \\\\frac{1}{x} \\\\)"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '\\( f(x)=1-x^2 \\) 在端点值相等且可导。', NULL, NULL, NULL, 2, '["中值定理"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m4-001', 'c1-m4-i1', 'calculus-1', 'c1-m4', 0, '基本积分', '求 \\( \\displaystyle \\int (3x^2+2x)\\,dx \\)。', '["x^3+x^2+C","x^3+x^2","x^3+x^2+1","x^3+x^2-C"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '逐项积分：\\( x^3+x^2+C \\)。', NULL, NULL, NULL, 2, '["不定积分"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
